  test "source report summary replays timeline lifecycle-state summaries" do
    planned = [
      %{
        id: :cmd_pending,
        type: :command,
        status: :planned,
        approval_status: :pending,
        starts_at_s: 10.0,
        ends_at_s: 20.0,
