             Schema.validate_artifact(manifest)

    assert Enum.any?(
             manifest["rows"],
             &(&1["import_action"] == "review_resource_suppression" and
                 &1["invalid_resource_summary_input"] == true and
                 get_in(&1, ["source_resource_summary", "raw_input"]) ==
                   "\"bad_resource_summary\"")
           )
  end

